import asyncio

async def test_host_request(type_name):
    payload = {"action": "request_demos"}
    try:
        result = await rlm.host_request(type_name, payload)
        return {"type": type_name, "success": True, "result": str(result)}
    except Exception as e:
        return {"type": type_name, "success": False, "error": str(e)[:100]}

asyncio.create_task(test_host_request("puzzle"))
